head.script:

scwin.onpageload = function() {
	var jsonData = [{col1:"a",col2:"a1",col3:"1000", col4:"a"}
					,{col1:"b",col2:"a2",col3:"1000", col4:"a"}
					,{col1:"c",col2:"a3",col3:"1000", col4:"a"}
					,{col1:"d",col2:"a4",col3:"1000", col4:"a"}
					,{col1:"e",col2:"a5",col3:"1000", col4:"a"}
					,{col1:"f",col2:"b1",col3:"1000", col4:"b"}
					,{col1:"g",col2:"b3",col3:"1000", col4:"b"}
					,{col1:"h",col2:"c1",col3:"1000", col4:"c"}
					,{col1:"i",col2:"c2",col3:"1000", col4:"c"}
					,{col1:"j",col2:"c3",col3:"1000", col4:"c"}
					,{col1:"k",col2:"d1",col3:"1000", col4:"d"}
					,{col1:"l",col2:"d2",col3:"1000", col4:"d"}
					,{col1:"n",col2:"d3",col3:"1000", col4:"d"}];
	dataList1.setJSON(jsonData);
};

scwin.onpageunload = function() {

};

scwin.summaryFormatFunction = function(data){
	var retdata = "";
	debugger;
	var tempArr = data.split(",");
	if(tempArr[1] == 1){
		retdata = " " + tempArr[0] + " Summary";
	}else{
		retdata =  " " + tempArr[0] + " " + tempArr[1] + ' [ ' + tempArr[2] + ' 건 ] ' 
	}

	return retdata;
};

scwin.testFormatFunction = function(data){
	return data + "원";
};

scwin.gridView1_ongroupby = function(options) {
			scwin.groupby_test(options);
		};
		scwin.groupby_test = function(options){
			//debugger;
			var flag = true;
			if(flag) {
				options.closeGroup = true; 

				options.groupbyHeader = [{colSpan: "5", inputType: "expression", expression: " toggle() + depthStr() + ' [ ' + count() + ' 건 ] ' ", align: "left" }];
				options.groupbyFooter = [
					{colSpan:"5",inputType: "expression", expression: " SUM('col3')", displayFormatter: "scwin.countFormatFunction", align: "center"}
				];

				gridView1.groupby( options ); //실제 groupby 실행

			} else {
				return false; 
			}
		};

		scwin.fn_formatter = function(data){

			return data + "_format";
		}

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate = function() {
		scwin.simulateWrapper('#gridView1_column6', 'drag-n-drop', {
			dx: 0,
			dy: -60
		});
	}

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('gridView1_groupbyZone_list_items_main').children[2].innerText == 'a_format';
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column6').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2grid_groupbyZone_column_value')[0].click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_groupbyZone_list_items_main').children[2].click()");
		WebSquare.wUnit.addCommand("pause", "400");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
